    Query.validateExpression("${filename:startsWith('T8MTXBC')\n" + ":or( ${filename:startsWith('C4QXABC')} )\n" + ":or( ${filename:startsWith('U6CXEBC')} )" + ":or( ${filename:startsWith('KYM3ABC')} )}", false);
}

