@Test
public void testLargeCharUTFLengths() {
    final String string64k = StringUtils.repeat(utfStringOneByte + utfStringTwoByte + utfStringThreeByte, 21845);
    assertEquals("test 64k char string should be 64k chars long", 65535, string64k.length());
    // drop half the chars going to utf of 64k bytes -- (1+1+1) * 21845 = 65535 chars which converts to (1+2+3) * 21845 = 131070 utf bytes so 1/2 is truncated
    assertEquals("test 64k char string truncated to 65,535 utf bytes should be 32768", 32768, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65535));
    // dropping bytes off the end of utf length
    // lost 2 byte char
    assertEquals("test 64k char string truncated to 65,534 utf bytes should be 32767", 32767, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65534));
    assertEquals("test 64k char string truncated to 65,533 utf bytes should be 32767", 32767, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65533));
    // lost 1 byte char
    assertEquals("test 64k char string truncated to 65,532 utf bytes should be 32766", 32766, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65532));
    // lost 3 byte char
    assertEquals("test 64k char string truncated to 65,531 utf bytes should be 32765", 32765, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65531));
    assertEquals("test 64k char string truncated to 65,530 utf bytes should be 32765", 32765, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65530));
    assertEquals("test 64k char string truncated to 65,529 utf bytes should be 32765", 32765, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65529));
    // lost 2 byte char (again)
    assertEquals("test 64k char string truncated to 65,528 utf bytes should be 32764", 32764, SchemaRecordWriter.getCharsInUTF8Limit(string64k, 65528));
}

@Test
public void testKeytabUserSuccessfulLoginAndLogout() throws LoginException {
    // perform login for user1
    final KerberosUser user1 = new KerberosKeytabUser(principal1.getName(), principal1KeytabFile.getAbsolutePath());
    user1.login();
    // perform login for user2
    final KerberosUser user2 = new KerberosKeytabUser(principal2.getName(), principal2KeytabFile.getAbsolutePath());
    user2.login();
    // verify user1 Subject only has user1 principal
    final Subject user1Subject = ((KerberosKeytabUser) user1).getSubject();
    final Set<Principal> user1SubjectPrincipals = user1Subject.getPrincipals();
    assertEquals(1, user1SubjectPrincipals.size());
    assertEquals(principal1.getName(), user1SubjectPrincipals.iterator().next().getName());
    // verify user2 Subject only has user2 principal
    final Subject user2Subject = ((KerberosKeytabUser) user2).getSubject();
    final Set<Principal> user2SubjectPrincipals = user2Subject.getPrincipals();
    assertEquals(1, user2SubjectPrincipals.size());
    assertEquals(principal2.getName(), user2SubjectPrincipals.iterator().next().getName());
    // call check/relogin and verify neither user performed a relogin
    assertFalse(user1.checkTGTAndRelogin());
    assertFalse(user2.checkTGTAndRelogin());
    // perform logout for both users
    user1.logout();
    user2.logout();
    // verify subjects have no more principals
    assertEquals(0, user1Subject.getPrincipals().size());
    assertEquals(0, user2Subject.getPrincipals().size());
}

