        repo.update(Collections.singletonList(new Object()), false);
        repo.update(Collections.singletonList(new Object()), false);
    } finally {
        repo.shutdown();
    }
    final WriteAheadRepository<Object> secondRepo = new MinimalLockingWriteAheadLog<>(path, numPartitions, serde, null);
    try {
        secondRepo.recoverRecords();
    } finally {
        secondRepo.shutdown();
    }
}

