@Test
public void testEntityTrackingStrategy() throws InitializationException {
    runner.setProperty(AbstractListProcessor.LISTING_STRATEGY, AbstractListProcessor.BY_ENTITIES);
    // Require a cache service.
    runner.assertNotValid();
    final DistributedCache trackingCache = new DistributedCache();
    runner.addControllerService("tracking-cache", trackingCache);
    runner.enableControllerService(trackingCache);
    runner.setProperty(ListedEntityTracker.TRACKING_STATE_CACHE, "tracking-cache");
    runner.setProperty(ListedEntityTracker.TRACKING_TIME_WINDOW, "10ms");
    runner.assertValid();
    proc.currentTimestamp.set(0L);
    runner.run();
    assertEquals(0, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    // Should list one entity.
    proc.addEntity("one", "one", 1, 1);
    proc.currentTimestamp.set(1L);
    runner.clearTransferState();
    runner.run();
    assertEquals(1, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(0).assertAttributeEquals(CoreAttributes.FILENAME.key(), "one");
    // Should not list any entity.
    proc.currentTimestamp.set(2L);
    runner.clearTransferState();
    runner.run();
    assertEquals(0, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    // Should list added entities.
    proc.currentTimestamp.set(10L);
    proc.addEntity("five", "five", 5, 5);
    proc.addEntity("six", "six", 6, 6);
    runner.clearTransferState();
    runner.run();
    assertEquals(2, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(0).assertAttributeEquals(CoreAttributes.FILENAME.key(), "five");
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(1).assertAttributeEquals(CoreAttributes.FILENAME.key(), "six");
    // Should be able to list entities having older timestamp than the previously listed entity.
    // But if its timestamp is out of tracking window, then it won't be picked.
    // Current timestamp = 13, and window = 10ms, meaning it can pick entities having timestamp 3 to 13.
    proc.currentTimestamp.set(13L);
    proc.addEntity("two", "two", 2, 2);
    proc.addEntity("three", "three", 3, 3);
    proc.addEntity("four", "four", 4, 4);
    runner.clearTransferState();
    runner.run();
    assertEquals(2, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(0).assertAttributeEquals(CoreAttributes.FILENAME.key(), "three");
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(1).assertAttributeEquals(CoreAttributes.FILENAME.key(), "four");
    // Can pick entity that has newer timestamp.
    // Can pick entity that has different size.
    proc.currentTimestamp.set(14L);
    proc.addEntity("five", "five", 7, 5);
    proc.addEntity("six", "six", 6, 16);
    runner.clearTransferState();
    runner.run();
    assertEquals(2, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(0).assertAttributeEquals(CoreAttributes.FILENAME.key(), "six");
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(1).assertAttributeEquals(CoreAttributes.FILENAME.key(), "five");
    // Reset state.
    // Current timestamp = 15, and window = 11ms, meaning it can pick entities having timestamp 4 to 15.
    proc.currentTimestamp.set(15L);
    // ConcreteListProcessor can reset state with any property.
    runner.setProperty(ListedEntityTracker.TRACKING_TIME_WINDOW, "11ms");
    runner.setProperty(ConcreteListProcessor.RESET_STATE, "1");
    runner.setProperty(ListedEntityTracker.INITIAL_LISTING_TARGET, "window");
    runner.clearTransferState();
    runner.run();
    assertEquals(3, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(0).assertAttributeEquals(CoreAttributes.FILENAME.key(), "four");
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(1).assertAttributeEquals(CoreAttributes.FILENAME.key(), "six");
    runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).get(2).assertAttributeEquals(CoreAttributes.FILENAME.key(), "five");
    // Reset state again.
    proc.currentTimestamp.set(20L);
    // ConcreteListProcessor can reset state with any property.
    runner.setProperty(ListedEntityTracker.INITIAL_LISTING_TARGET, "all");
    runner.setProperty(ConcreteListProcessor.RESET_STATE, "2");
    runner.clearTransferState();
    runner.run();
    // All entities should be picked, one to six.
    assertEquals(6, runner.getFlowFilesForRelationship(AbstractListProcessor.REL_SUCCESS).size());
}

@Test
public void testBasicUsage() {
    final ExternalProcedure p = new ExternalProcedure();
    try {
        // Although a catch-exception has to be caught each possible call,
        // usually the error handling logic will be the same.
        // Ends up having a lot of same code.
        final int r1 = p.divide(4, 2);
        assertEquals(2, r1);
    } catch (Exception e) {
        e.printStackTrace();
    }
    final Context context = new Context();
    final ExceptionHandler<Context> handler = new ExceptionHandler<>();
    // Using handler can avoid the try catch block with reusable error handling logic.
    handler.execute(context, 6, i -> {
        final int r2 = p.divide(i, 2);
        assertEquals(3, r2);
    });
    // If return value is needed, use AtomicReference.
    AtomicReference<Integer> r = new AtomicReference<>();
    handler.execute(context, 8, i -> r.set(p.divide(i, 2)));
    assertEquals(4, r.get().intValue());
    // If no exception mapping is specified, any Exception thrown is wrapped by ProcessException.
    try {
        final Integer nullInput = null;
        handler.execute(context, nullInput, i -> r.set(p.divide(i, 2)));
        fail("Exception should be thrown because input is null.");
    } catch (ProcessException e) {
        assertTrue(e.getCause() instanceof NullPointerException);
    }
}

@Test
public void testHandling() {
    final ExternalProcedure p = new ExternalProcedure();
    final Context context = new Context();
    final ExceptionHandler<Context> handler = new ExceptionHandler<>();
    handler.mapException(exceptionMapping);
    handler.onError(createInputErrorHandler());
    // Benefit of handler is being able to externalize error handling, make it simpler.
    handler.execute(context, 4, i -> {
        final int r = p.divide(i, 2);
        assertEquals(2, r);
    });
    // Null pointer exception.
    final Integer input = null;
    handler.execute(context, input, i -> {
        p.divide(i, 2);
        fail("Shouldn't reach here.");
    });
    // Divide by zero.
    handler.execute(context, 0, i -> {
        p.divide(2, i);
        fail("Shouldn't reach here.");
    });
}

@Test
public void testHandlingLoop() {
    final ExternalProcedure p = new ExternalProcedure();
    final Context context = new Context();
    final ExceptionHandler<Context> handler = new ExceptionHandler<>();
    handler.mapException(exceptionMapping);
    handler.onError(createArrayInputErrorHandler());
    // It's especially handy when looping through inputs. [a, b, expected result]
    Integer[][] inputs = new Integer[][] { { 4, 2, 2 }, { null, 2, 999 }, { 2, 0, 999 }, { 10, 2, 999 }, { 8, 2, 4 } };
    Arrays.stream(inputs).forEach(input -> handler.execute(context, input, (in) -> {
        final Integer r = p.divide(in[0], in[1]);
        // This is safe because if p.divide throws error, this code won't be executed.
        assertEquals(in[2], r);
    }));
    AtomicReference<Integer> r = new AtomicReference<>();
    for (Integer[] input : inputs) {
        if (!handler.execute(context, input, (in) -> {
            r.set(p.divide(in[0], in[1]));
            context.count++;
        })) {
            // Handler returns false when it fails.
            // Cleaner if-exception-continue-next-input can be written cleaner.
            continue;
        }
        assertEquals(input[2], r.get());
    }
    assertEquals("Successful inputs", 2, context.count);
}

