@Test(timeout = 10000)
public void testSunnyCase() throws InterruptedException, IOException {
    final Queue<FlowFileRecord> flowFiles = new LinkedList<>();
    final FlowFileRecord flowFile1 = new MockFlowFileRecord(5);
    final FlowFileRecord flowFile2 = new MockFlowFileRecord(8);
    flowFiles.offer(flowFile1);
    flowFiles.offer(flowFile2);
    final Map<FlowFileRecord, InputStream> contentMap = new HashMap<>();
    contentMap.put(flowFile1, new ByteArrayInputStream("hello".getBytes()));
    contentMap.put(flowFile2, new ByteArrayInputStream("good-bye".getBytes()));
    final FlowFileContentAccess contentAccess = contentMap::get;
    final RegisteredPartition partition = new RegisteredPartition("unit-test-connection", () -> false, flowFiles::poll, NOP_FAILURE_CALLBACK, (ff, nodeId) -> {
    }, () -> LoadBalanceCompression.DO_NOT_COMPRESS, () -> true);
    final SocketChannel socketChannel = SocketChannel.open(new InetSocketAddress("localhost", port));
    socketChannel.configureBlocking(false);
    final PeerChannel peerChannel = new PeerChannel(socketChannel, null, "unit-test");
    final LoadBalanceSession transaction = new LoadBalanceSession(partition, contentAccess, new StandardLoadBalanceFlowFileCodec(), peerChannel, 30000, new SimpleLimitThreshold(100, 10_000_000));
    Thread.sleep(100L);
    while (transaction.communicate()) {
    }
    assertTrue(transaction.isComplete());
    socketChannel.close();
    final Checksum expectedChecksum = new CRC32();
    final ByteArrayOutputStream expectedOut = new ByteArrayOutputStream();
    // Protocol Version
    expectedOut.write(1);
    final DataOutputStream expectedDos = new DataOutputStream(new CheckedOutputStream(expectedOut, expectedChecksum));
    expectedDos.writeUTF("unit-test-connection");
    expectedDos.write(LoadBalanceProtocolConstants.CHECK_SPACE);
    expectedDos.write(LoadBalanceProtocolConstants.MORE_FLOWFILES);
    // metadata length
    expectedDos.writeInt(68);
    // 1 attribute
    expectedDos.writeInt(1);
    // length of attribute
    expectedDos.writeInt(4);
    expectedDos.write("uuid".getBytes());
    expectedDos.writeInt(flowFile1.getAttribute("uuid").length());
    expectedDos.write(flowFile1.getAttribute("uuid").getBytes());
    // lineage start date
    expectedDos.writeLong(flowFile1.getLineageStartDate());
    // entry date
    expectedDos.writeLong(flowFile1.getEntryDate());
    expectedDos.write(LoadBalanceProtocolConstants.DATA_FRAME_FOLLOWS);
    expectedDos.writeShort(5);
    expectedDos.write("hello".getBytes());
    expectedDos.write(LoadBalanceProtocolConstants.NO_DATA_FRAME);
    expectedDos.write(LoadBalanceProtocolConstants.MORE_FLOWFILES);
    // metadata length
    expectedDos.writeInt(68);
    // 1 attribute
    expectedDos.writeInt(1);
    // length of attribute
    expectedDos.writeInt(4);
    expectedDos.write("uuid".getBytes());
    expectedDos.writeInt(flowFile2.getAttribute("uuid").length());
    expectedDos.write(flowFile2.getAttribute("uuid").getBytes());
    // lineage start date
    expectedDos.writeLong(flowFile2.getLineageStartDate());
    // entry date
    expectedDos.writeLong(flowFile2.getEntryDate());
    expectedDos.write(LoadBalanceProtocolConstants.DATA_FRAME_FOLLOWS);
    expectedDos.writeShort(8);
    expectedDos.write("good-bye".getBytes());
    expectedDos.write(LoadBalanceProtocolConstants.NO_DATA_FRAME);
    expectedDos.write(LoadBalanceProtocolConstants.NO_MORE_FLOWFILES);
    expectedDos.writeLong(expectedChecksum.getValue());
    expectedDos.write(LoadBalanceProtocolConstants.COMPLETE_TRANSACTION);
    final byte[] expectedSent = expectedOut.toByteArray();
    while (received.size() < expectedSent.length) {
        Thread.sleep(10L);
    }
    final byte[] dataSent = received.toByteArray();
    assertArrayEquals(expectedSent, dataSent);
    assertEquals(Arrays.asList(flowFile1, flowFile2), transaction.getFlowFilesSent());
}

@Test(timeout = 10000)
public void testLargeContent() throws InterruptedException, IOException {
    final byte[] content = new byte[66000];
    for (int i = 0; i < 66000; i++) {
        content[i] = 'A';
    }
    final Queue<FlowFileRecord> flowFiles = new LinkedList<>();
    final FlowFileRecord flowFile1 = new MockFlowFileRecord(content.length);
    flowFiles.offer(flowFile1);
    final Map<FlowFileRecord, InputStream> contentMap = new HashMap<>();
    contentMap.put(flowFile1, new ByteArrayInputStream(content));
    final FlowFileContentAccess contentAccess = contentMap::get;
    final RegisteredPartition partition = new RegisteredPartition("unit-test-connection", () -> false, flowFiles::poll, NOP_FAILURE_CALLBACK, (ff, nodeId) -> {
    }, () -> LoadBalanceCompression.DO_NOT_COMPRESS, () -> true);
    final SocketChannel socketChannel = SocketChannel.open(new InetSocketAddress("localhost", port));
    socketChannel.configureBlocking(false);
    final PeerChannel peerChannel = new PeerChannel(socketChannel, null, "unit-test");
    final LoadBalanceSession transaction = new LoadBalanceSession(partition, contentAccess, new StandardLoadBalanceFlowFileCodec(), peerChannel, 30000, new SimpleLimitThreshold(100, 10_000_000));
    Thread.sleep(100L);
    while (transaction.communicate()) {
    }
    socketChannel.close();
    final Checksum expectedChecksum = new CRC32();
    final ByteArrayOutputStream expectedOut = new ByteArrayOutputStream();
    // Protocol Version
    expectedOut.write(1);
    final DataOutputStream expectedDos = new DataOutputStream(new CheckedOutputStream(expectedOut, expectedChecksum));
    expectedDos.writeUTF("unit-test-connection");
    expectedDos.write(LoadBalanceProtocolConstants.CHECK_SPACE);
    expectedDos.write(LoadBalanceProtocolConstants.MORE_FLOWFILES);
    // metadata length
    expectedDos.writeInt(68);
    // 1 attribute
    expectedDos.writeInt(1);
    // length of attribute
    expectedDos.writeInt(4);
    expectedDos.write("uuid".getBytes());
    expectedDos.writeInt(flowFile1.getAttribute("uuid").length());
    expectedDos.write(flowFile1.getAttribute("uuid").getBytes());
    // lineage start date
    expectedDos.writeLong(flowFile1.getLineageStartDate());
    // entry date
    expectedDos.writeLong(flowFile1.getEntryDate());
    // first data frame
    expectedDos.write(LoadBalanceProtocolConstants.DATA_FRAME_FOLLOWS);
    expectedDos.writeShort(LoadBalanceSession.MAX_DATA_FRAME_SIZE);
    expectedDos.write(Arrays.copyOfRange(content, 0, LoadBalanceSession.MAX_DATA_FRAME_SIZE));
    // second data frame
    expectedDos.write(LoadBalanceProtocolConstants.DATA_FRAME_FOLLOWS);
    expectedDos.writeShort(content.length - LoadBalanceSession.MAX_DATA_FRAME_SIZE);
    expectedDos.write(Arrays.copyOfRange(content, LoadBalanceSession.MAX_DATA_FRAME_SIZE, content.length));
    expectedDos.write(LoadBalanceProtocolConstants.NO_DATA_FRAME);
    expectedDos.write(LoadBalanceProtocolConstants.NO_MORE_FLOWFILES);
    expectedDos.writeLong(expectedChecksum.getValue());
    expectedDos.write(LoadBalanceProtocolConstants.COMPLETE_TRANSACTION);
    final byte[] expectedSent = expectedOut.toByteArray();
    while (received.size() < expectedSent.length) {
        Thread.sleep(10L);
    }
    final byte[] dataSent = received.toByteArray();
    assertArrayEquals(expectedSent, dataSent);
    assertEquals(Arrays.asList(flowFile1), transaction.getFlowFilesSent());
}

@Test(timeout = 20_000)
public void testNewNodeAdded() throws IOException, InterruptedException {
    localNodeId = new NodeIdentifier("unit-test-local", "localhost", 7090, "localhost", 7090, "localhost", 7090, null, null, null, false, null);
    nodeIdentifiers.add(localNodeId);
    // Create the server
    final int timeoutMillis = 1000;
    final LoadBalanceProtocol loadBalanceProtocol = new StandardLoadBalanceProtocol(serverFlowFileRepo, serverContentRepo, serverProvRepo, flowController, ALWAYS_AUTHORIZED);
    final SSLContext sslContext = null;
    final NioAsyncLoadBalanceClientRegistry clientRegistry = new NioAsyncLoadBalanceClientRegistry(createClientFactory(sslContext), 1);
    clientRegistry.start();
    final NodeConnectionStatus connectionStatus = mock(NodeConnectionStatus.class);
    when(connectionStatus.getState()).thenReturn(NodeConnectionState.CONNECTED);
    when(clusterCoordinator.getConnectionStatus(any(NodeIdentifier.class))).thenReturn(connectionStatus);
    final NioAsyncLoadBalanceClientTask clientTask = new NioAsyncLoadBalanceClientTask(clientRegistry, clusterCoordinator, eventReporter);
    final Thread clientThread = new Thread(clientTask);
    final SocketLoadBalancedFlowFileQueue flowFileQueue = new SocketLoadBalancedFlowFileQueue(queueId, new NopConnectionEventListener(), processScheduler, clientFlowFileRepo, clientProvRepo, clientContentRepo, resourceClaimManager, clusterCoordinator, clientRegistry, flowFileSwapManager, swapThreshold, eventReporter);
    flowFileQueue.setFlowFilePartitioner(new RoundRobinPartitioner());
    final int serverCount = 5;
    final ConnectionLoadBalanceServer[] servers = new ConnectionLoadBalanceServer[serverCount];
    try {
        flowFileQueue.startLoadBalancing();
        clientThread.start();
        for (int i = 0; i < serverCount; i++) {
            final ConnectionLoadBalanceServer server = new ConnectionLoadBalanceServer("localhost", 0, sslContext, 8, loadBalanceProtocol, eventReporter, timeoutMillis);
            servers[i] = server;
            server.start();
            final int loadBalancePort = server.getPort();
            // Create the Load Balanced FlowFile Queue
            final NodeIdentifier nodeId = new NodeIdentifier("unit-test-" + i, "localhost", 8090 + i, "localhost", 8090, "localhost", loadBalancePort, null, null, null, false, null);
            nodeIdentifiers.add(nodeId);
            clusterEventListeners.forEach(listener -> listener.onNodeAdded(nodeId));
            for (int j = 0; j < 2; j++) {
                final Map<String, String> attributes = new HashMap<>();
                attributes.put("greeting", "hello");
                final MockFlowFileRecord flowFile = new MockFlowFileRecord(attributes, 0L);
                flowFileQueue.put(flowFile);
            }
        }
        final int totalFlowFileCount = 7;
        // Wait up to 10 seconds for the server's FlowFile Repository to be updated
        final long endTime = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(10L);
        while (serverRepoRecords.size() < totalFlowFileCount && System.currentTimeMillis() < endTime) {
            Thread.sleep(10L);
        }
        assertFalse("Server's FlowFile Repo was never fully updated", serverRepoRecords.isEmpty());
        assertEquals(totalFlowFileCount, serverRepoRecords.size());
        for (final RepositoryRecord serverRecord : serverRepoRecords) {
            final FlowFileRecord serverFlowFile = serverRecord.getCurrent();
            assertEquals("hello", serverFlowFile.getAttribute("greeting"));
        }
        while (clientRepoRecords.size() < totalFlowFileCount) {
            Thread.sleep(10L);
        }
        assertEquals(totalFlowFileCount, clientRepoRecords.size());
        for (final RepositoryRecord clientRecord : clientRepoRecords) {
            assertEquals(RepositoryRecordType.DELETE, clientRecord.getType());
        }
    } finally {
        clientTask.stop();
        flowFileQueue.stopLoadBalancing();
        clientRegistry.getAllClients().forEach(AsyncLoadBalanceClient::stop);
        Arrays.stream(servers).filter(Objects::nonNull).forEach(ConnectionLoadBalanceServer::stop);
    }
}

