    dos.write(CHECK_SPACE);
    dos.write(MORE_FLOWFILES);
    writeAttributes(attributes, dos);
    writeContent("hello".getBytes(), dos);
    dos.write(MORE_FLOWFILES);
    writeAttributes(Collections.singletonMap("uuid", "unit-test-id-2"), dos);
