/*
     * This test simply validates that generated IDs are comparable and
     * sequentially correct where each subsequent ID is > previous ID.
     */
@Test
public void validateIdOrdering() throws Exception {
    UUID seed = ComponentIdGenerator.generateId();
    UUID currentId1 = ComponentIdGenerator.generateId();
    UUID currentId2 = ComponentIdGenerator.generateId();
    UUID currentId3 = ComponentIdGenerator.generateId();
    UUID id1 = new UUID(currentId1.getMostSignificantBits(), UUID.nameUUIDFromBytes((currentId1.toString() + seed.toString()).getBytes(StandardCharsets.UTF_8)).getLeastSignificantBits());
    UUID id2 = new UUID(currentId2.getMostSignificantBits(), UUID.nameUUIDFromBytes((currentId2.toString() + seed.toString()).getBytes(StandardCharsets.UTF_8)).getLeastSignificantBits());
    UUID id3 = new UUID(currentId3.getMostSignificantBits(), UUID.nameUUIDFromBytes((currentId3.toString() + seed.toString()).getBytes(StandardCharsets.UTF_8)).getLeastSignificantBits());
    List<UUID> list = new ArrayList<>();
    list.add(id2);
    list.add(id3);
    list.add(id1);
    Collections.sort(list);
    assertEquals(id1, list.get(0));
    assertEquals(id2, list.get(1));
    assertEquals(id3, list.get(2));
}

