@Test
public void testBecomePrimaryWithNewerLocalState() throws InitializationException {
    final long now = System.currentTimeMillis();
    final Map<String, String> cells = new HashMap<>();
    cells.put("greeting", "hello");
    cells.put("name", "nifi");
