    // should fail because of the semicolon
    runner.assertAllFlowFilesTransferred(PutHive3QL.REL_SUCCESS, 1);
    runner.getFlowFilesForRelationship(PutHive3QL.REL_SUCCESS).forEach(f -> f.assertAttributeEquals(PutHive3QL.ATTR_OUTPUT_TABLES, "PERSONS"));
