    runner.enqueue("<<?>>");
    runner.run();
    runner.assertTransferCount(GetMongo.REL_FAILURE, 1);
    runner.assertTransferCount(GetMongo.REL_SUCCESS, 0);
    runner.assertTransferCount(GetMongo.REL_ORIGINAL, 0);
}

