@Test
public void testXQueries() throws Exception {
    /* count matches */
    doXqueryTest(XML_SNIPPET, "count(*:fruitbasket/fruit)", Arrays.asList("7"));
    doXqueryTest(XML_SNIPPET, "count(//fruit)", Arrays.asList("7"));
    /* Using a namespace */
    doXqueryTest(XML_SNIPPET, "declare namespace fb = \"http://namespace/1\"; count(fb:fruitbasket/fruit)", Arrays.asList("7"));
    /* determine if node exists */
    doXqueryTest(XML_SNIPPET, "boolean(//fruit[1])", Arrays.asList("true"));
    doXqueryTest(XML_SNIPPET, "boolean(//fruit[100])", Arrays.asList("false"));
    /* XML first match */
    doXqueryTest(XML_SNIPPET, "//fruit[1]", Arrays.asList("<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\" taste=\"crisp\"><!-- Apples are my favorite --><name>apple</name><color>red</color></fruit>"));
    /* XML last match */
    doXqueryTest(XML_SNIPPET, "//fruit[count(//fruit)]", Arrays.asList("<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\"><name>none</name><color/></fruit>"));
    /* XML first match wrapped */
    doXqueryTest(XML_SNIPPET, "<wrap>{//fruit[1]}</wrap>", Arrays.asList("<?xml version=\"1.0\" encoding=\"UTF-8\"?><wrap><fruit xmlns:ns=\"http://namespace/1\" taste=\"crisp\"><!-- Apples are my favorite --><name>apple</name><color>red</color></fruit></wrap>"));
    /* XML all matches (multiple results) */
    doXqueryTest(XML_SNIPPET, "//fruit", Arrays.asList("<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\" taste=\"crisp\"><!-- Apples are my favorite --><name>apple</name><color>red</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\"><name>apple</name><color>green</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\"><name>banana</name><color>yellow</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\" taste=\"sweet\"><name>orange</name><color>orange</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\"><name>blueberry</name><color>blue</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\" taste=\"tart\"><name>raspberry</name><color>red</color></fruit>", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><fruit xmlns:ns=\"http://namespace/1\"><name>none</name><color/></fruit>"));
    /* XML all matches wrapped (one result)*/
    doXqueryTest(XML_SNIPPET, "<wrap>{//fruit}</wrap>", Arrays.asList("<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + "<wrap>" + "<fruit xmlns:ns=\"http://namespace/1\" taste=\"crisp\"><!-- Apples are my favorite --><name>apple</name><color>red</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\"><name>apple</name><color>green</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\"><name>banana</name><color>yellow</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\" taste=\"sweet\"><name>orange</name><color>orange</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\"><name>blueberry</name><color>blue</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\" taste=\"tart\"><name>raspberry</name><color>red</color></fruit>" + "<fruit xmlns:ns=\"http://namespace/1\"><name>none</name><color/></fruit>" + "</wrap>"));
    /* String all matches fruit names*/
    doXqueryTest(XML_SNIPPET, "for $x in //fruit return $x/name/text()", Arrays.asList(fruitNames));
    /* String first match fruit name (XPath)*/
    doXqueryTest(XML_SNIPPET, "//fruit[1]/name/text()", Arrays.asList("apple"));
    /* String first match fruit color (XPath)*/
    doXqueryTest(XML_SNIPPET, "//fruit[1]/color/text()", Arrays.asList("red"));
    /* String first match fruit name (XQuery)*/
    doXqueryTest(XML_SNIPPET, "for $x in //fruit[1] return string-join(($x/name/text() , $x/color/text()), ' - ')", Arrays.asList("apple - red"));
    /* String first match fruit & color (one result)*/
    doXqueryTest(XML_SNIPPET, "for $x in //fruit[1] return string-join(($x/name/text() , $x/color/text()), ' - ')", Arrays.asList("apple - red"));
    /* String all matches fruit & color (multiple results)*/
    doXqueryTest(XML_SNIPPET, "for $x in //fruit return string-join(($x/name/text() , $x/color/text()), ' - ')", Arrays.asList("apple - red", "apple - green", "banana - yellow", "orange - orange", "blueberry - blue", "raspberry - red", "none"));
    /* String all matches fruit & color (single, newline delimited result)*/
    doXqueryTest(XML_SNIPPET, "string-join((for $y in (for $x in //fruit return string-join(($x/name/text() , $x/color/text()), ' - ')) return $y), '\n')", Arrays.asList("apple - red\n" + "apple - green\n" + "banana - yellow\n" + "orange - orange\n" + "blueberry - blue\n" + "raspberry - red\n" + "none"));
    /* String all matches fruit & color using "let" (single, newline delimited result)*/
    doXqueryTest(XML_SNIPPET, "string-join((for $y in (for $x in //fruit let $d := string-join(($x/name/text() , $x/color/text()), ' - ')  return $d) return $y), '\n')", Arrays.asList("apple - red\n" + "apple - green\n" + "banana - yellow\n" + "orange - orange\n" + "blueberry - blue\n" + "raspberry - red\n" + "none"));
    /* String all matches name only, comma delimited (one result)*/
    doXqueryTest(XML_SNIPPET, "string-join((for $x in //fruit return $x/name/text()), ', ')", Arrays.asList("apple, apple, banana, orange, blueberry, raspberry, none"));
    /* String all matches color and name, comma delimited (one result)*/
    doXqueryTest(XML_SNIPPET, "string-join((for $y in (for $x in //fruit return string-join(($x/color/text() , $x/name/text()), ' ')) return $y), ', ')", Arrays.asList("red apple, green apple, yellow banana, orange orange, blue blueberry, red raspberry, none"));
    /* String all matches color and name, comma delimited using let(one result)*/
    doXqueryTest(XML_SNIPPET, "string-join((for $y in (for $x in //fruit let $d := string-join(($x/color/text() , $x/name/text()), ' ')  return $d) return $y), ', ')", Arrays.asList("red apple, green apple, yellow banana, orange orange, blue blueberry, red raspberry, none"));
    /* Query for attribute */
    doXqueryTest(XML_SNIPPET, "string(//fruit[1]/@taste)", Arrays.asList("crisp"));
    /* Query for comment */
    doXqueryTest(XML_SNIPPET, "//fruit/comment()", Arrays.asList(" Apples are my favorite "));
    /* Query for processing instruction */
    doXqueryTest(XML_SNIPPET, "//processing-instruction()[name()='xml-stylesheet']", Arrays.asList("type=\"text/xsl\" href=\"foo.xsl\""));
}

