    out.assertContentEquals("WO$1RD");
    runner.enqueue("wo$1r$2d".getBytes());
    runner.run();
    runner.assertAllFlowFilesTransferred(ReplaceText.REL_SUCCESS, 3);
    out = runner.getFlowFilesForRelationship(ReplaceText.REL_SUCCESS).get(2);
